"""
    Recursively convert inputs to uppercase strings, except if None.

    Parameters
    ----------
    inp : str or list of str
        Object to be converted to upper.

    Returns
    -------
    str, list or None

    """
def to_upper(inp: Any) -> object {
    if (inp is None) {
        return None;
    }
    if isinstance(inp, `list) {
        return [to_upper(s) for s in inp];
    }
    return str(inp).upper();
}

"""
    figuring out the allele number corresponding to likelihood position
    ploidy P and N alternate alleles
    https://samtools.github.io/hts-specs/VCFv4.3.pdf
    :param p: the ploidy as int
    :param n: alt alleles as int
    :param index:
    :return: list with genotype numbers as strings (it's how pyvcf has it)
    """
def genotype_from_likelyhood_index(p: Any, n: Any, index: Any) -> object {
    def recursive_order(_p: Any, _n: Any, alleles: Any, suffix: Any = []) -> object {
        for a in range(_n) {
            if (_p == 1) {
                alleles.append(([str(a)] + suffix));
            } elif (_p > 1) {
                recursive_order((_p - 1), (a + 1), alleles, ([str(a)] + suffix));
            }
        }
    }
    alleles_list = [];
    recursive_order(p, n, alleles_list);
    return alleles_list[index];
}

"""
    Returns the name of the Happy stack for the specified deployment
    Note: This will only work with deployment={dev,stage,prod} and will not work with rdev!
    :param deployment: dev, stage or prod
    :return:
    """
def get_happy_stack_name(deployment: Any) -> str {
    return f"{deployment}-{deployment}stack";
}

