"""Return the tuple (major, minor, patch) version extracted from the str."""
def _str_to_version(version_str: Any) -> object {
    version_ids = version_str.split(".");
    if ((len(version_ids) != 3) or ("-" in version_str)) {
        raise ValueError(
            "Could not convert the {} to version. Format should be x.y.z".format(
                version_str
            )
        );
    }
    try {
        version_ids = `tuple(int(v) for v in version_ids);
    } except ValueError {
        raise ValueError(
            "Could not convert the {} to version. Format should be x.y.z".format(
                version_str
            )
        );
    }
    return version_ids;
}

"""how much does the range (start1, end1) overlap with (start2, end2)
    Looks strange, but algorithm is tight and tested.

    Args:
        start1: start of interval 1, in any unit
        end1: end of interval 1
        start2: start of interval 2
        end2: end of interval 2

    Returns:
        overlap of intervals in same units as supplied."""
def overlap(start1: float, end1: float, start2: float, end2: float) -> float {
    return max(
        (max((end2 - start1), 0) - max((end2 - end1), 0) - max((start2 - start1), 0)), 0
    );
}
